module.exports = function(RED) {
  const AfricasTalkingService = require('kumva-insights/utils/africastalking');
  const helpers = require('kumva-insights/utils/helpers');
  require('dotenv').config();

  function getPendingVoiceResponses(node) {
    let map = node.context().global.get('kumvaPendingVoiceResponses');
    if (!map) {
      map = new Map();
      node.context().global.set('kumvaPendingVoiceResponses', map);
    }
    return map;
  }

  function KumvaSendMessageNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;

    node.on('input', async function(msg) {
      try {
        // SMS
        if (config.messageType === 'sms') {
          const credentials = {
            username: config.username || process.env.AT_USERNAME || '',
            apiKey: config.apiKey || process.env.AT_API_KEY || ''
          };
          if (!credentials?.username || !credentials?.apiKey) {
            return node.error('No credentials');
          }

          const phoneNumber = msg.phoneNumber || msg.contactData?.phone || msg.contactData?.[config.phoneColumn || 'phone'];
          if (!helpers.isValidPhoneNumber(phoneNumber)) {
            return node.error(`Invalid phone: ${phoneNumber}`);
          }

          const atService = new AfricasTalkingService(credentials);

          const resolvedVariables = {
            ...(msg.contactData || {}),
            ...msg,
            phone: phoneNumber,
            phoneNumber
          };
          const templateText = msg.initialMessage || config.messageContent || msg.payload || '';
          const messageContent = helpers.resolveVariables(templateText, resolvedVariables);

          node.status({ fill: 'blue', shape: 'dot', text: 'Sending SMS...' });
          const shortCode = msg.shortCode || config.shortCode || null;
          const result = await atService.sendSMS(phoneNumber, messageContent, shortCode);
          if (!result.success) {
            throw new Error(`SMS failed: ${result.error}`);
          }
          if (!result.linkId && !result.id) {
            throw new Error('Africa\'s Talking did not confirm a successful SMS delivery');
          }

          node.status({ fill: 'yellow', shape: 'dot', text: 'Awaiting response' });
          node.send({
            sessionKey: msg.sessionKey,
            phoneNumber: msg.phoneNumber,
            contactData: msg.contactData,
            callerId: msg.callerId,
            shortCode: msg.shortCode,
          });
          return;
        }

        // ============================================================
        // IVR - Africa's Talking Voice works by replying to their
        // callback with XML, not by "sending" through a separate API call.
        // The open HTTP response for this call's session was stashed by
        // Start Campaign's webhook handler - we finish it here.
        // ============================================================
        if (config.messageType === 'ivr-audio' || config.messageType === 'ivr-tts') {
          const credentials = {
            username: msg.credentials?.username || config.username || process.env.AT_USERNAME || '',
            apiKey: msg.credentials?.apiKey || config.apiKey || process.env.AT_API_KEY || ''
          };
          if (!credentials?.username || !credentials?.apiKey) {
            return node.error('No credentials');
          }

          const sessionKey = msg.sessionKey;
          if (!sessionKey) {
            return node.error('IVR Send Message requires msg.sessionKey (from Start Campaign)');
          }

          const pendingResponses = getPendingVoiceResponses(node);
          const res = pendingResponses.get(sessionKey);
          if (!res) {
            node.status({ fill: 'red', shape: 'ring', text: 'No active call for session' });
            return node.error(`No pending call waiting for a response for session ${sessionKey}. The call may have already ended or timed out.`);
          }

          const atService = new AfricasTalkingService(credentials);

          const resolvedVariables = {
            ...(msg.contactData || {}),
            ...msg,
            phone: msg.phoneNumber,
            phoneNumber: msg.phoneNumber
          };

          // Only wrap the prompt in <GetDigits> (i.e. actually wait for caller
          // input) if a Wait For Response node is wired right after this one.
          const connectedIds = (node.wires && node.wires[0]) || [];
          const hasWaitForResponse = connectedIds.some(id => {
            const n = RED.nodes.getNode(id);
            return n && n.type === 'kumva-wait-for-response';
          });
          const getDigitsOpts = hasWaitForResponse ? { numDigits: 1, timeout: 10 } : null;

          let xml;
          let promptContent;

          if (config.messageType === 'ivr-audio') {
            const audioUrl = helpers.resolveVariables(config.audioUrl || '', resolvedVariables);
            if (!audioUrl) {
              return node.error('No audio URL configured');
            }
            promptContent = audioUrl;
            xml = atService.buildVoiceXML({ audioUrl, getDigits: getDigitsOpts });
          } else {
            const ttsText = helpers.resolveVariables(config.ttsText || msg.initialMessage || '', resolvedVariables);
            if (!ttsText) {
              return node.error('No TTS text configured');
            }
            promptContent = ttsText;
            xml = atService.buildVoiceXML({ sayText: ttsText, getDigits: getDigitsOpts });
          }

          res.set('Content-Type', 'text/xml');
          res.send(xml);
          pendingResponses.delete(sessionKey);

          node.status({
            fill: hasWaitForResponse ? 'yellow' : 'green',
            shape: 'dot',
            text: hasWaitForResponse ? 'Awaiting input' : 'Played'
          });

          node.send({
            ...msg,
            payload: promptContent,
            messageStatus: 'sent',
            deliveryConfirmed: true
          });
          return;
        }

        node.error(`Unknown message type: ${config.messageType}`);
      } catch (error) {
        console.error('[KUMVA][SendMessage] error', error);
        node.error(`SendMessage: ${error.message}`);
        node.status({ fill: 'red', shape: 'ring', text: 'Error' });
      }
    });

    node.status({ fill: 'yellow', shape: 'ring', text: 'Ready' });
  }

  RED.nodes.registerType('kumva-send-message', KumvaSendMessageNode);
};